import sys

def main():
    data = sys.stdin.read().split()
    pos = 0
    n = int(data[pos]); pos += 1
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = int(data[pos]), int(data[pos + 1]); pos += 2
        adj[u].append(v)
        adj[v].append(u)
    q = int(data[pos]); pos += 1
    qs = [[] for _ in range(n)]
    for i in range(q):
        node, val = int(data[pos]), int(data[pos + 1]); pos += 2
        qs[node].append((val, i))
    BITS = 18
    size = (n + 1) * (BITS + 1) + 2
    c0 = [0] * size
    c1 = [0] * size
    cnt = [0] * size
    tot = 1  # node 0 is the trie root

    def update(x, d):
        nonlocal tot
        cur = 0
        for b in range(BITS - 1, -1, -1):
            if (x >> b) & 1:
                nxt = c1[cur]
                if not nxt:
                    nxt = tot; tot += 1; c1[cur] = nxt
            else:
                nxt = c0[cur]
                if not nxt:
                    nxt = tot; tot += 1; c0[cur] = nxt
            cur = nxt
            cnt[cur] += d

    def query(v):
        cur = 0
        res = 0
        for b in range(BITS - 1, -1, -1):
            if (v >> b) & 1:
                want, other = c0[cur], c1[cur]
            else:
                want, other = c1[cur], c0[cur]
            if want and cnt[want] > 0:
                res |= 1 << b
                cur = want
            else:
                cur = other
        return res

    ans = [0] * q
    parent = [-1] * n
    stack = [(0, 0)]
    while stack:
        u, state = stack.pop()
        if state == 0:
            update(u, 1)
            for val, i in qs[u]:
                ans[i] = query(val)
            stack.append((u, 1))
            for w in adj[u]:
                if w != parent[u]:
                    parent[w] = u
                    stack.append((w, 0))
        else:
            update(u, -1)
    print(' '.join(map(str, ans)))

