    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[][] edges = new int[n - 1][2];
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken(); queries[i][0] = (int) in.nval;
            in.nextToken(); queries[i][1] = (int) in.nval;
        }
        int[] ans = maxGeneticDifference(n, edges, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i]).append(i + 1 < ans.length ? " " : "\n");
